cd /workspaces/semio && node -e "
const fs = require('fs');
const content = fs.readFileSync('elements/ui/index.tsx', 'utf8');
// Extract the English translation block
const enStart = content.indexOf(\"  en: {\n    translation: JSON.parse(String.raw\");
const jsonStart = content.indexOf('{', enStart + 60);
// Find the closing backtick
let depth = 0;
let jsonEnd = -1;
for (let i = jsonStart; i < content.length; i++) {
  if (content[i] === '{') depth++;
  if (content[i] === '}') depth--;
  if (depth === 0) { jsonEnd = i + 1; break; }
}
const jsonStr = content.substring(jsonStart, jsonEnd);
try {
  const parsed = JSON.parse(jsonStr);
  // Check the kit settings path
  const kitSettings = parsed?.compose?.sketchpad?.app?.kit?.settings;
  console.log('Kit settings exists:', !!kitSettings);
  console.log('Kit settings keys:', Object.keys(kitSettings || {}));
  console.log('theme label:', JSON.stringify(kitSettings?.theme));
  console.log('diagram.chargeStrength:', JSON.stringify(kitSettings?.diagram?.chargeStrength));
  console.log('language:', JSON.stringify(kitSettings?.language));
  console.log('device:', JSON.stringify(kitSettings?.device));
  console.log('expertise:', JSON.stringify(kitSettings?.expertise));
  console.log('mode:', JSON.stringify(kitSettings?.mode));
} catch(e) {
  console.error('JSON parse error:', e.message);
}
"

