const fs = require("fs");
const content = fs.readFileSync("elements/ui/index.tsx", "utf8");
const marker = "  en: {\n    translation: JSON.parse(String.raw";
const enStart = content.indexOf(marker);
const backtickPos = content.indexOf("`", enStart + marker.length);
const jsonStart = backtickPos + 1;
let depth = 0;
let jsonEnd = -1;
for (let i = jsonStart; i < content.length; i++) {
  if (content[i] === "{") depth++;
  if (content[i] === "}") depth--;
  if (depth === 0) { jsonEnd = i + 1; break; }
}
const jsonStr = content.substring(jsonStart, jsonEnd);

// For each "settings" key we found, trace the JSON object path
function getPathAtOffset(jsonStr, targetOffset) {
  let depth = 0;
  const stack = [];
  let lastKey = null;
  let inString = false;
  let escaping = false;
  let keyBuffer = "";
  let collectingKey = false;
  for (let i = 0; i < targetOffset; i++) {
    const ch = jsonStr[i];
    if (escaping) { escaping = false; continue; }
    if (ch === "\\\\") { escaping = true; continue; }
    if (ch === "\"" && !inString) {
      inString = true;
      keyBuffer = "";
      collectingKey = true;
      continue;
    }
    if (ch === "\"" && inString) {
      inString = false;
      if (collectingKey) lastKey = keyBuffer;
      collectingKey = false;
      continue;
    }
    if (inString) { keyBuffer += ch; continue; }
    if (ch === "{") {
      stack.push(lastKey || "?");
      lastKey = null;
    }
    if (ch === "}") {
      stack.pop();
    }
    if (ch === ":") collectingKey = false;
    if (ch === ",") collectingKey = false;
  }
  return stack.join(".");
}

// Find settings at interesting lines
const offsets = [];
let pos = 0;
while (true) {
  pos = jsonStr.indexOf("\"settings\":", pos);
  if (pos === -1) break;
  const fileOffset = jsonStart + pos;
  const lineNum = content.substring(0, fileOffset).split("\\n").length;
  const path = getPathAtOffset(jsonStr, pos);
  console.log("Line ~" + lineNum + ": " + path + ".settings");
  offsets.push(pos);
  pos += 10;
}
'

