import json

with open('elements/ui/index.tsx', 'r') as f:
    content = f.read()

blocks = content.split('JSON.parse(String.raw\`')
for i, block in enumerate(blocks[1:], 1):
    end = block.find('\`)')
    if end == -1:
        continue
    json_str = block[:end]

    # Check for duplicate keys using a custom decoder
    # JSON standard: last key wins. Let's use object_pairs_hook
    duplicates = []
    def find_duplicates(pairs, path=''):
        seen = {}
        for key, value in pairs:
            full_path = f'{path}.{key}' if path else key
            if key in seen:
                duplicates.append(full_path)
            seen[key] = value
        return seen

    try:
        json.loads(json_str, object_pairs_hook=lambda pairs: find_duplicates(pairs))
    except:
        pass

    lang = 'de' if i == 1 else 'en'
    if duplicates:
        print(f'Block {i} ({lang}): Found {len(duplicates)} duplicate keys:')
        for d in duplicates:
            print(f'  - {d}')
    else:
        print(f'Block {i} ({lang}): No duplicate keys found')
"

