    if i != 2:  # Only English
        continue
    end = block.find('\`)')
    if end == -1:
        continue
    json_str = block[:end]

    # Find duplicate keys with FULL path
    duplicates = []
    def find_duplicates(pairs, path=''):
        seen = {}
        result = {}
        for key, value in pairs:
            full_path = f'{path}.{key}' if path else key
            if key in seen:
                duplicates.append(full_path)
            seen[key] = True
            if isinstance(value, dict):
                result[key] = value
            else:
                result[key] = value
        return result

    class DuplicateDecoder(json.JSONDecoder):
        def __init__(self, *args, **kwargs):
            super().__init__(object_pairs_hook=self._hook, *args, **kwargs)
            self.path_stack = []

        def _hook(self, pairs):
            seen = {}
            result = {}
            for key, value in pairs:
                if key in seen:
                    # Find the full path
                    duplicates.append(key)
                seen[key] = True
                result[key] = value
            return result

    decoder = DuplicateDecoder()
    decoder.decode(json_str)

    print(f'Duplicate keys in English translation:')
    for d in duplicates:
        print(f'  - {d}')
