import json

with open('elements/ui/index.tsx', 'r') as f:
    content = f.read()

blocks = content.split('JSON.parse(String.raw`')
en_block = blocks[2]
en_json_str = en_block[:en_block.index('`)')]

# Parse with object_pairs_hook to detect ALL duplicates with their full paths
duplicates = []

def make_checker(path):
    def check(pairs):
        seen = set()
        result = {}
        for key, value in pairs:
            full = f"{path}.{key}" if path else key
            if key in seen:
                duplicates.append(full)
            seen.add(key)
            result[key] = value
        return result
    return check

# Unfortunately can't pass path info through json.loads easily
# Let's use a different approach - track nesting level
import io

class DuplicateDetector(json.JSONDecoder):
    def __init__(self):
        self.found = []
        self.depth = 0
        self.path_by_depth = {}
        super().__init__(object_pairs_hook=self._check)

    def _check(self, pairs):
        seen = {}
        result = {}
        for key, value in pairs:
            if key in seen:
                self.found.append(key)
            seen[key] = True
            result[key] = value
        return result

detector = DuplicateDetector()
detector.decode(en_json_str)
print(f"Total duplicate keys found: {len(detector.found)}")
for d in detector.found:
    print(f"  - {d}")
