import json

with open('elements/ui/index.tsx', 'r') as f:
    content = f.read()

blocks = content.split('JSON.parse(String.raw`')

for idx, lang in [(1, "German"), (2, "English")]:
    block = blocks[idx]
    json_str = block[:block.index('`)')]

    duplicates = []
    def check_pairs(pairs):
        seen = {}
        result = {}
        for key, value in pairs:
            if key in seen:
                sibling_keys = list(seen.keys())[:3]
                duplicates.append((key, sibling_keys))
            seen[key] = True
            result[key] = value
        return result

    data = json.loads(json_str, object_pairs_hook=check_pairs)

    if duplicates:
        print(f"{lang}: {len(duplicates)} duplicate keys:")
        for dup_key, siblings in duplicates:
            print(f'  "{dup_key}" (siblings: {siblings})')
    else:
        print(f"{lang}: No duplicate keys - CLEAN ✓")

    # Verify key settings exist
    for app in ['home', 'kit', 'docs']:
        settings = data.get('compose', {}).get('sketchpad', {}).get('app', {}).get(app, {}).get('settings', {})
        keys = list(settings.keys()) if isinstance(settings, dict) else []
        print(f"  {app}.settings keys: {keys}")

